                if grid[new_row][new_col] == '.' and not visited[new_row][new_col]:
                    visited[new_row][new_col] = True
                    parents[(new_row, new_col)] = (current_row, current_col)
                    if (new_row, new_col) == goal:
                        path = [(new_row, new_col)]
                        current = (new_row, new_col)
                        while current != start:
                            current = parents[current]
                            path.append(current)
                        path.reverse()
                        return path
                    queue.append((new_row, new_col))
