def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    visited.add(start)
    path = [start]

    def dfs(current):
        if current == goal:
            return path.copy()
        for dr, dc in directions:
            new_row, new_col = current[0] + dr, current[1] + dc
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]):
                next_cell = (new_row, new_col)
                if grid[new_row][new_col] == '.' and next_cell not in visited:
                    visited.add(next_cell)
                    path.append(next_cell)
                    result = dfs(next_cell)
                    if result is not None:
                        return result
                    path.pop()
                    visited.remove(next_cell)
        return None

    result_path = dfs(start)
    return result_path if result_path else []
