        return []
    if grid[goal[0]][goal[1]] == '#':
        return []
    # Check if start is goal
    if start == goal:
        return [start]
    # DFS
    stack = [(start, [start])]
    while stack:
        current, path = stack.pop()
        if current == goal:
            return path
        # Explore neighbors
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            new_row = current[0] + dr
            new_col = current[1] + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '.' and (new_row, new_col) not in path:
                    new_path = path + [(new_row, new_col)]
                    stack.append( ( (new_row, new_col), new_path ) )
    # No path found
    return []
